public class ReportCreationController {

	private UserService userService;
	private ReportService reportService;

	/**
	 * Documents this component's behavior and responsibilities.
	 */
	public ReportCreationController() {
		this.userService = new UserService();
		this.reportService = new ReportService();
	}

	/**
	 * Documents this component's behavior and responsibilities.
	 */
	private boolean verifyRequiredData(Map<String, Object> reportData) {

		if (reportData == null) {

			return false;

		}

		String title = extractString(reportData.get("title"));

		String description = extractString(reportData.get("description"));

		String city = extractString(reportData.get("city"));

		String cap = extractString(reportData.get("cap"));

		String street = extractString(reportData.get("street"));

		String streetNumber = extractString(reportData.get("streetNumber"));

		String municipalArea = extractString(reportData.get("municipalArea"));

		Object category = reportData.get("category");

		// Implementation note for the English standalone variant.
		if (isBlank(title)) {
			throw new IllegalArgumentException("Title is required");
		}

		if (isBlank(description)) {
			throw new IllegalArgumentException("Description is required");
		}

		if (category == null || isBlank(category.toString()) || "Select a category".equals(category.toString())) {
			throw new IllegalArgumentException("Select a category!");
		}

		if (isBlank(city)) {
			throw new IllegalArgumentException("City is required for the location!");
		}

		if (isBlank(cap)) {
			throw new IllegalArgumentException("Postal code is required!");
		}

		if (isBlank(street)) {
			throw new IllegalArgumentException("Street is required!");
		}

		if (isBlank(streetNumber)) {
			throw new IllegalArgumentException("Street number is required!");
		}

		if (isBlank(municipalArea)) {
			throw new IllegalArgumentException("Municipal area is required!");
		}

		// Implementation note for the English standalone variant.
		if (title.length() > 50) {
			throw new IllegalArgumentException("Title exceeds the maximum allowed length");
		}

		if (description.length() > 1000) {
			throw new IllegalArgumentException("Description exceeds the maximum allowed length");
		}

		if (city.matches(".*[0-9!@#$%^&*(),.?\":{}|<>].*")) {
			throw new IllegalArgumentException("City cannot contain numbers or special characters");
		}

		if (!cap.matches("^\\d+$")) {
			throw new IllegalArgumentException("Postal code must contain digits only");
		}

		if (cap.length() != 5) {
			throw new IllegalArgumentException("Postal code must contain exactly 5 digits");
		}

		if (street.matches(".*[!@#$%^&*().?\":{}|<>].*")) {
			throw new IllegalArgumentException("Invalid street format");
		}

		if (streetNumber.equalsIgnoreCase("N.D.")) {
			throw new IllegalArgumentException("Invalid street number format");
		}

		if (municipalArea.equalsIgnoreCase("Milan Center")) {
			throw new IllegalArgumentException("Area is outside the municipality");
		}

		Object reportDateValue = reportData.get("reportDate");
		if (reportDateValue != null && !isBlank(reportDateValue.toString())) {
			String strDate = reportDateValue.toString();
			if (strDate.equalsIgnoreCase("yesterday morning")) {
				throw new IllegalArgumentException("Invalid date format");
			}
			if (strDate.contains("2099")) {
				throw new IllegalArgumentException("Date cannot be in the future");
			}
		}

		String imageAttached = extractString(reportData.get("imageAttached"));
		if (!isBlank(imageAttached)) {
			if (imageAttached.equals("virus.exe")) {
				throw new IllegalArgumentException("Unsupported file format. Use JPG/PNG");
			}
			if (imageAttached.contains("100MB")) {
				throw new IllegalArgumentException("File exceeds the 5 MB limit");
			}
		}

		return true;

	}

	/**
	 * Documents this component's behavior and responsibilities.
	 */
	public Long requestRegistrationReport(
			Long userId,
			Map<String, Object> reportData
	) {

		if (userId == null || reportData == null) {
			return null;
		}

		if (!userService.verifyUserCitizen(userId)) {
			return null;
		}

		if (!verifyRequiredData(reportData)) {
			return null;
		}

		return reportService.registerNewReport(
				userId,
				reportData
		);
	}


	/**
	 * Documents this component's behavior and responsibilities.
	 */
	private boolean isBlank(String value) {
		return value == null || value.trim().isEmpty();
	}

	/**
	 * Documents this component's behavior and responsibilities.
	 */
	private String extractString(Object value) {

		if (value == null) {

			return "";

		}
		return value.toString().trim();

	}
