public class ReportDetailsController {

	private UserService userService;
	private ReportService reportService;

	public ReportDetailsController() {

		this.userService = new UserService();
		this.reportService = new ReportService();
	}

	public boolean verifyDetailsAccess(
			Long userId,
			Long reportId
	) {

		if (userId == null || reportId == null) {
			return false;
		}

		Map<String, Object> details =
				reportService.retrieveDetailsReport(
						userId,
						reportId
				);

		if (details == null || details.isEmpty()) {
			return false;
		}

		if (userService.isMunicipalOperator(userId)) {
			return true;
		}

		if (userService.verifyUserCitizen(userId)) {
			Long citizenId = extractLong(details.get("citizenId"));

			return citizenId != null && citizenId.equals(userId);
		}

		return false;
	}

	/**
	 * Documents this component's behavior and responsibilities.
	 */
	public Map<String, Object> retrieveDetailsReport(
			Long userId,
			Long reportId
	) {

		if (userId == null || reportId == null) {
			return null;
		}

		if (!verifyDetailsAccess(userId, reportId)) {
			return null;
		}

		Map<String, Object> details =
				reportService.retrieveDetailsReport(
						userId,
						reportId
				);

		if (details == null) {
			return null;
		}

		List<Map<String, Object>> history =
				reportService.retrieveHistoryReport(
						userId,
						reportId
				);

		details.put("history", history);

		return details;
	}

	public List<Map<String, Object>> retrieveHistoryReport(
			Long userId,
			Long reportId
	) {

		if (userId == null || reportId == null) {
			return null;
		}

		if (!verifyDetailsAccess(userId, reportId)) {
			return null;
		}

		return reportService.retrieveHistoryReport(
				userId,
				reportId
		);
	}

	private Long extractLong(Object value) {

		if (value == null) {
			return null;
		}

		if (value instanceof Long) {
			return (Long) value;
		}

		if (value instanceof Integer) {
			return ((Integer) value).longValue();
		}

		try {
			return Long.parseLong(value.toString());
		} catch (NumberFormatException e) {
			return null;
		}
	}
